25	// NewClient creates a new authenticated API client with an explicit bearer token.
26	func NewClient(token string) *Client {
27		return &Client{
28			httpClient: &http.Client{
29				Transport: &bearerTransport{
30					token: token,
31					base:  http.DefaultTransport,
32				},
33			},
34			baseURL: BaseURL(),
35		}
